import{_ as g}from"./C6gRvd95.js";import{m,f,c as n,a as o,g as w,n as y,k,t as v,u as t,o as l}from"./CBnRMYeL.js";import{u as b}from"./BKCGliV8.js";const _={class:"section-padding"},T={class:"container thinnest-content"},S={class:"mb-3"},B=["src"],V={__name:"what-song-are-you-working-on",setup(C){const c=m(),{currentRoute:d}=c,e=f.find(i=>i.slug===d.value.fullPath.replace("/articles/",""));let s=`${e.title}`,a=`${e.description}`,h=`Stefan, Stefan Auvache Bradley, Bradley, ${e.categories.join(", ")}, ${e.keywords}`,u=`www.stefanauvache.com/articles/${e.slug}`;return b({title:s,ogTitle:s,description:a,ogDescription:a,keywords:h,canonical:u,robots:"index, follow"}),(i,r)=>{const p=g;return l(),n("section",_,[o("div",T,[o("div",null,[o("h1",S,v(t(e).title),1),t(e).image!=="title.jpg"?(l(),n("img",{key:0,src:`/img/articles/${t(e).image}`,alt:"",class:"mb-3"},null,8,B)):y("",!0),r[0]||(r[0]=k('<p class="quote">“How is an idea created? Maybe sometimes it strikes like lightning, but mostly it will develop slowly through intensive search under numerous mistakes.” - Rudolph Diesel</p><p>Sir Paul McCartney has written over a thousand songs. His song Yesterday, which he wrote during his time with The Beatles, has been covered more than any other song in the history of recorded music. Over 2,200 versions of his song have been recorded or performed by various artists. A year before the song was released, Paul played a working version of Yesterday for fellow musician Eric Clapton. The lyrics went like this:</p><p>“Scrambled eggs... Everybody calls me scrambled eggs.”</p><p>The most covered song of all time - scrambled eggs.</p><p>Paul McCartney is a prolific songwriter for several reasons. Here are two.</p><p>First, he writes a lot of songs.</p><p>Volume is key in finding ideas with potential. Whether it be personal pride or fear of wasting effort, people refuse to &quot;kill their darlings&quot; (William Faulkner). They stick to the songs they’ve written like their lives depend on it. To create something great, generate a lot of ideas. Then learn to discern which of those ideas have potential and which do not.</p><p>Second, he works to refine his ideas with potential into great songs.</p><p>Companies fail to gain traction because founders don’t spend enough time working on the core idea of their product. Books fail to entertain because authors build stories on foundations that haven’t been properly refined. Great products are built on great ideas, and great ideas are sculpted out of unrefined ideas that hold potential. When you have a good idea, take the time to make it great.</p><p>Paul McCartney found an idea on the guitar that had great potential. To work out the music and melody, he used the first lyrics that came to his mind. Once the music was ready, he worked on lyrics until the song was complete.</p><p>What song are you working on? What problems are you trying to solve? Generate ideas. Find the ones with potential. Then refine those until you have something great.</p>',11))]),w(p,{slug:t(e).slug},null,8,["slug"])])])}}};export{V as default};
